/*播放器图标样式*/
.replay-button svg {
  width: 25px;
  height: 25px;}
.replay-button svg circle {
  fill:#231F20;
  stroke:#ffffff;}   /*外圆*/
.nightMode .replay-button svg circle {
  fill:#dce0df;
  stroke:#000000;} 
.replay-button svg path {
  stroke:#91C462;
  fill: #91C462;}   /*内三角*/
.nightMode .replay-button svg path {
  stroke:#4e4d4d;
  fill: #4e4d4d;}  

.highlight {font-weight:bold;color:#b22222;}
.nightMode .highlight{color:#ccffff;}




